-          __ bind(L_fill_2);
-          __ test_bit(tmp_reg, count, 0);
-          __ beqz(tmp_reg, L_exit);
+          // Two bytes misalignment happens only for byte and short (char) arrays.
+          __ test_bit(tmp_reg, to, 1);
